=== driver/desktop/app.go contents ===
package desktop

import "fyne.io/fyne/v2"

// App represents a desktop application with extended system integration capabilities.
//
// Since: 2.5
type App interface {
	// SetSystemTrayMenu sets the menu that appears when interacting with the system tray icon.
	// This allows applications to provide quick access to common actions from the system tray.
	SetSystemTrayMenu(menu *fyne.Menu)

	// SystemTrayMenu returns the menu currently set for the system tray icon, or nil if none is set.
	SystemTrayMenu() *fyne.Menu
}

data.content:
// Refresh triggers all windows displaying this menu to update its contents.
//
// Since: 2.5
func (m *Menu) Refresh() {
	// This will be implemented by the driver to refresh menu display
	// The driver implementation will iterate through windows and update menus
}


// MenuItem is a single item within any menu, it contains a display Label and Action function that is called when tapped.
type MenuItem struct {
	ChildMenu *Menu
	// Since: 2.1
	IsQuit      bool
	IsSeparator bool
	Label       string
	Action      func()
	// Since: 2.1
	Disabled bool
	// Since: 2.1
	Checked bool
	// Icon is an optional icon to display alongside the menu item.
	//
	// Since: 2.5
	Icon Resource

